begin transaction read only;
set local statement_timeout='30s';
select candidate.status,candidate.source_recovery_blocked,candidate.attempt_count>=6 at_attempt_limit,candidate.last_error_code,count(*) eligible_operations from accounts.credential_operations candidate join accounts.principals principal on principal.id=candidate.principal_id where principal.status='active' and candidate.status in ('auth_applied','failed') and candidate.source_backend in ('sanity','supabase') and candidate.last_error_code in ('CREDENTIAL_MIRROR_PENDING','CREDENTIAL_MIRROR_DEAD_LETTER') and candidate.sessions_revoked_at is not null and candidate.source_applied_at is not null and candidate.source_applied_revision is not null and exists(select 1 from auth.users u join accounts.principal_auth_users identity_link on identity_link.user_id=u.id where u.id=candidate.user_id and identity_link.principal_id=candidate.principal_id) and exists(select 1 from migration.source_documents source where source.legacy_sanity_id=candidate.source_document_id and not source.tombstoned and source.document_type='referral' and jsonb_typeof(candidate.source_mutation->'set')='object' and source.payload @> (candidate.source_mutation->'set') and jsonb_typeof(candidate.source_mutation->'unset')='array' and not exists(select 1 from jsonb_array_elements_text(candidate.source_mutation->'unset') key where source.payload ? key)) group by 1,2,3,4 order by 1,2,3,4;
rollback;
